    significance: '《马关条约》是继《南京条约》以来最严重的不平等条约。条约规定割让台湾全岛及所有附属各岛屿、澎湖列岛给日本，赔偿日本军费白银2亿两，开放沙市、重庆、苏州、杭州为商埠，允许日本在中国通商口岸投资设厂。这一条约使中国半殖民地化程度大大加深，刺激了帝国主义列强瓜分中国的野心，引发了"瓜分狂潮"，也促使中国人民开始觉醒，推动了维新变法运动的兴起。',
