    relatedEvents: [],
    background: '第一次世界大战结束后，《凡尔赛和约》对德国实施苛刻的制裁，巨额赔款与领土丧失导致德国经济崩溃、民族情绪激化。1929年全球经济大萧条进一步加剧了德国的社会危机，为纳粹党的崛起提供了土壤。',
    cause: '1933年1月30日，德国总统兴登堡任命希特勒为总理，纳粹党利用国会纵火案等事件逐步建立独裁统治，实施"一体化"政策，取缔其他政党，建立秘密警察（盖世太保）和集中营体系。',
    significance: '这一事件标志着纳粹德国独裁统治的开始，其极端民族主义、种族主义和扩张主义政策最终导致第二次世界大战的爆发以及对犹太人、罗姆人、残疾人等群体的系统性屠杀（大屠杀），成为20世纪人类历史上最黑暗的篇章之一。纽伦堡审判确认了纳粹政权的反人类罪行，确立了国际法上的刑事责任原则。',
